import Joi from 'joi'

const registrationRoutes = [
  {
    method: 'GET',
    path: '/register/name',
    handler: (_request, h) => {
      return h.view('registration/name', {
        pageTitle: 'What is your full name?'
      })
    }
  },
  {
    method: 'POST',
    path: '/register/name',
    options: {
      validate: {
        payload: Joi.object({
          fullName: Joi.string().trim().required().messages({
            'string.empty': 'Enter your full name',
            'any.required': 'Enter your full name'
          }),
          notes: Joi.string().trim().max(2000).allow('').optional().messages({
            'string.max': 'Notes must be 2000 characters or fewer'
          }),
          crumb: Joi.string()
        }),
        failAction: (_request, h, error) => {
          const errors = error.details.map((detail) => ({
            text: detail.message,
            href: `#${detail.context.key}`
          }))
          return h.view('registration/name', {
            pageTitle: 'Error: What is your full name?',
            errorSummary: errors,
            errors: Object.fromEntries(
              error.details.map((d) => [d.context.key, { text: d.message }])
            ),
            values: _request.payload
          }).takeover()
        }
      }
    },
    handler: (request, h) => {
      const { fullName, notes } = request.payload
      // Persist minimal registration data in a secure cookie for the confirmation page
      h.state('registration', { fullName, notes })
      return h.redirect('/register/confirmation')
    }
  },
  {
    method: 'GET',
    path: '/register/confirmation',
    handler: (request, h) => {
      const registration = request.state.registration || {}
      return h.view('registration/confirmation', {
        pageTitle: 'Check your details',
        fullName: registration.fullName,
        notes: registration.notes
      })
    }
  }
]

